"""Clean-room PIL.Image — path-guarded open/save."""

import builtins
import os

def is_path(fp):
    return isinstance(fp, (str, bytes))

class Image:
    def save(self, fp, format=None, **params):
        if is_path(fp):
            with builtins.open(fp, "wb") as f:
                f.write(b"")
            if format == "cleanup":
                os.remove(fp)
            return
        fp.write(b"")

def open(fp, mode="r"):
    if is_path(fp):
        with builtins.open(fp, "rb") as f:
            f.read()
        return Image()
    fp.read()
    return Image()
